          <tr>
            <td style="padding:24px 32px 0;">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
                <tr>
                  <td width="28" valign="top" style="font-size:15px;line-height:1.65;color:#7466F1;font-weight:700;">1</td>
                  <td style="font-size:15px;line-height:1.65;color:#374151;padding-bottom:12px;">
