      </td>
    </tr>
  </table>', NULL, ARRAY['app_url', 'first_name', 'unsubscribe_url']::text[], 'auto'),
  ('pack_ladder', 'en', 'pack ladder', 'More songs, same budget', '<div style="display:none;max-height:0;overflow:hidden;opacity:0;">
