                  <td style="padding:12px 0;border-top:1px solid #e5e7eb;color:#374151;">$10</td>
                  <td style="padding:12px 0;border-top:1px solid #e5e7eb;color:#374151;">2,300</td>
                  <td style="padding:12px 0;border-top:1px solid #e5e7eb;color:#374151;">230</td>
                  <td align="right" style="padding:12px 0;border-top:1px solid #e5e7eb;color:#059669;font-weight:600;">+15%</td>
                </tr>
                <tr>
                  <td style="padding:14px 0;border-top:1px solid #e5e7eb;background:#f5f3ff;color:#111827;font-weight:700;border-radius:8px 0 0 8px;">$20</td>
                  <td style="padding:14px 0;border-top:1px solid #e5e7eb;background:#f5f3ff;color:#111827;font-weight:700;">5,500</td>
